import {initAppearance} from './appearance.js';
import {mountNarrative,initNarrative} from './narrative.js';
import {mountCalendar,validDate} from './calendar.js';
import {documentTargets,resolveTarget} from './document-links.js';
import {editorMarkup,mountEditor} from './editor.js';
import {renderOverview,customizeOverview,mountOverview} from './overview.js';
import {initSidebar,closeMobileSidebar} from './sidebar.js';
import {uid,tabs,state,world,save,createWorld,escapeHTML as e,sanitize,plain,imageURL,imageFile,prepareWorld} from './store.js';
import {mountGlobe} from './globe.js';
const $=s=>document.querySelector(s), main=$('#main');let view='home',folderFilter='',selectedNote='',selectedMap='',selectedPin='',cleanup=()=>{},saveTimer;const isMac=/Mac|iPhone|iPad/.test(navigator.platform);
const counts=()=>({notes:world().notes.length,characters:world().characters.length,plot:world().plot.length,bestiary:world().bestiary.length,maps:world().maps.length});
const toast=message=>{const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3500);};
window.addEventListener('storagefull',()=>toast('O armazenamento está cheio. Exporte um backup e remova imagens para liberar espaço.'));
function persist(){clearTimeout(saveTimer);save();}function scheduleSave(){ $('#saveStatus').textContent='Salvando…';clearTimeout(saveTimer);saveTimer=setTimeout(save,350);}
function sidebar(){const w=world();$('#workspaceButton').innerHTML=`<span class="world-icon">✧</span><span><strong>${e(w.name)}</strong><small>${e(w.subtitle)}</small></span><span class="chevron">⌄</span>`;$('#crumbWorld').textContent=w.name;$('#crumbPage').textContent=view==='settings'?'Configurações':view==='folder'?(w.folders.find(f=>f.id===folderFilter)?.name||'Pasta'):tabs[view]?.[1]||'Visão geral';const enabled=w.enabled.filter(t=>tabs[t]),children=enabled.filter(t=>t!=='home'),navButton=t=>`<button data-view="${t}" class="${view===t?'active':''}" ${view===t?'aria-current="page"':''}><span class="nav-icon">${tabs[t][0]}</span>${tabs[t][1]}${counts()[t]!==undefined?`<span class="nav-count">${counts()[t]}</span>`:''}</button>`;$('#nav').innerHTML=(enabled.includes('home')?navButton('home'):'')+(children.length?`<details class="universe-nav-folder" id="universeNavFolder" ${w.navigationCollapsed?'':'open'}><summary class="${children.includes(view)?'contains-active':''}"><span class="nav-icon" aria-hidden="true">▱</span><span>Meu universo</span><span class="universe-nav-chevron" aria-hidden="true">⌄</span></summary><div class="universe-nav-children">${children.map(navButton).join('')}</div></details>`:'');const group=$('#universeNavFolder');if(group)group.ontoggle=()=>{if(!group.isConnected)return;const collapsed=!group.open;if(Boolean(w.navigationCollapsed)!==collapsed){w.navigationCollapsed=collapsed;persist();}};$('#folders').innerHTML=w.folders.map(f=>`<button class="folder-row" data-folder="${f.id}"><span>▱</span>${e(f.name)}<span class="nav-count">${w.folderNotes.filter(n=>n.folder===f.id).length}</span></button>`).join('');document.body.classList.toggle('dark',state.theme==='dark');}
function navigate(next,options={}){persist();cleanup();cleanup=()=>{};view=next;if(!world().enabled.includes(view)&&view!=='settings'&&view!=='folder')view='home';folderFilter=options.folder||'';if(options.note)selectedNote=options.note;closeMobileSidebar();sidebar();render();window.scrollTo(0,0);}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
const btn=(text,action,extra='')=>`<button class="button ${extra}" data-action="${action}">${text}</button>`;
function narrativePage(){cleanup();cleanup=mountNarrative(main,world(),view,{modal,field,save:scheduleSave,heading,btn,openDocument,notify:toast,confirmDelete});}
function render(){({connections:narrativePage,timeline:narrativePage,scenes:narrativePage,home:homePage,calendar:calendarPage,notes:notesPage,folder:notesPage,characters:()=>entitiesPage('characters'),bestiary:()=>entitiesPage('bestiary'),plot:plotPage,maps:mapsPage,globe:globePage,settings:settingsPage}[view]||homePage)();}
function homePage(sectionsOpen=false){cleanup();main.innerHTML=renderOverview(world(),counts(),heading,btn,state);cleanup=mountOverview(main,world(),{save:scheduleSave,notify:toast,rerender:homePage,sectionsOpen,openDocument,navigate:next=>{if(!world().enabled.includes(next))world().enabled.push(next);navigate(next);}});}
function openDocument(id){const target=resolveTarget(world(),id);if(!target){toast('Esta página não está mais disponível neste ambiente.');return;}if(target.type==='notes'&&!world().enabled.includes('notes'))world().enabled.push('notes');navigate(target.type,{folder:target.folder||'',note:target.id});}
function calendarPage(){cleanup=mountCalendar(main,world(),{modal,field,save:persist,navigate:target=>openDocument(target.id),confirmDelete,heading,btn});}
function activeNotes(){return view==='folder'?world().folderNotes:world().notes;}
function notesPage(){cleanup();cleanup=()=>{};const w=world(),inFolder=view==='folder',notes=activeNotes().filter(n=>!inFolder||n.folder===folderFilter);let n=notes.find(n=>n.id===selectedNote)||notes[0];selectedNote=n?.id||'';main.innerHTML=`<div class="page">${heading(inFolder?'SUAS PASTAS':'PALAVRAS QUE CONSTROEM MUNDOS',e(inFolder?(w.folders.find(f=>f.id===folderFilter)?.name||'Pasta'):'Notas & documentos'),inFolder?'Documentos desta pasta, independentes da aba de notas.':'Um espaço independente para suas notas e primeiras linhas.',btn('＋ Novo documento','note'))}${inFolder?'<div class="toolbar">'+btn('Renomear pasta','renameFolder','ghost')+btn('Excluir pasta','deleteFolder','ghost')+'</div>':''}<div class="editor-layout"><div class="note-list">${notes.map(note=>`<button class="note-item ${n?.id===note.id?'active':''}" data-note="${note.id}"><strong>${e(note.emoji||'▤')} ${e(note.title)}</strong><small>${e(plain(note.body).slice(0,36))||'Uma página em branco'}</small></button>`).join('')||'<p class="help">Nenhum documento por aqui.</p>'}</div>${n?editorMarkup(n):'<div class="empty"><h2>O começo de alguma coisa.</h2><p>Uma nova página para o que você imaginar.</p>'+btn('Criar documento','note')+'</div>'}</div></div>`;if(n)cleanup=mountEditor(n,{onChange:scheduleSave,onTitle:()=>{scheduleSave();const label=main.querySelector('.note-item.active strong');if(label)label.textContent=(n.emoji||'▤')+' '+n.title;},notify:toast,documents:documentTargets(w),openDocument});}
function entitiesPage(kind){const creature=kind==='bestiary',items=world()[kind];main.innerHTML=`<div class="page">${heading(creature?'ENTRE O MITO E O DESCONHECIDO':'TODA VIDA CARREGA UMA HISTÓRIA',creature?'Bestiário':'Personagens',creature?'Catalogue as criaturas que tornam seu mundo extraordinário.':'Conheça os desejos, segredos e contradições de quem habita seu universo.',btn(creature?'＋ Nova criatura':'＋ Novo personagem',creature?'beast':'character'))}<div class="toolbar"><input type="search" id="entitySearch" placeholder="${creature?'Buscar criaturas…':'Buscar personagens…'}" aria-label="Buscar fichas"><span class="help">${items.length} ${creature?'criaturas catalogadas':'personagens neste mundo'}</span></div><div class="cards" id="entityCards"></div></div>`;function cards(q=''){$('#entityCards').innerHTML=items.filter(it=>(it.name+' '+it.role+' '+it.description).toLowerCase().includes(q.toLowerCase())).map(it=>`<button class="card" data-entity="${it.id}" data-kind="${kind}">${imageURL(it.image)?`<img class="card-image" src="${imageURL(it.image)}" alt="${e(it.name)}" loading="lazy">`:`<div class="card-placeholder">${creature?'♧':e(it.name[0])}</div>`}<div class="card-body"><span class="eyebrow">${e(it.role||'Uma história por contar')}</span><h2>${e(it.name)}</h2><p>${e(it.description||'Abra a ficha e dê vida a esta história.')}</p><div class="card-meta"><span>${e(it.species||'Não definido')}</span><span>Abrir ficha ↗</span></div></div></button>`).join('')||'<div class="empty"><h2>Nenhuma ficha encontrada.</h2><p>Crie uma nova ficha ou tente outra busca.</p></div>'; }cards();$('#entitySearch').oninput=ev=>cards(ev.target.value);}
const stages={idea:'Ideias',writing:'Em desenvolvimento',done:'Concluído'};
function plotPage(){main.innerHTML=`<div class="page">${heading('O FIO QUE CONECTA A HISTÓRIA','Trama & plot','Organize os acontecimentos. Arraste as cenas para acompanhar seu progresso.',btn('＋ Novo acontecimento','plot'))}<div class="board">${Object.entries(stages).map(([status,label])=>`<section class="board-column" data-stage="${status}"><h3>${label} <span>${world().plot.filter(p=>p.status===status).length}</span></h3>${world().plot.filter(p=>p.status===status).map(p=>`<article class="plot-card" draggable="true" data-plot="${p.id}" tabindex="0" role="button" aria-label="Editar ${e(p.title)}"><span class="eyebrow">${e(p.act)}</span><h2>${e(p.title)}</h2><p>${e(p.description)}</p><div class="plot-foot"><span>◌ ${label}</span><span>Editar ↗</span></div></article>`).join('')}<button class="text-link" data-action="plot" data-stage-new="${status}">＋ Adicionar acontecimento</button></section>`).join('')}</div></div>`;document.querySelectorAll('.plot-card').forEach(card=>{card.ondragstart=ev=>ev.dataTransfer.setData('text/plain',card.dataset.plot);card.onkeydown=ev=>{if(ev.key==='Enter')editPlot(card.dataset.plot);};});document.querySelectorAll('.board-column').forEach(col=>{col.ondragover=ev=>{ev.preventDefault();col.classList.add('drag-over');};col.ondragleave=()=>col.classList.remove('drag-over');col.ondrop=ev=>{ev.preventDefault();const p=world().plot.find(p=>p.id===ev.dataTransfer.getData('text/plain'));if(p){p.status=col.dataset.stage;persist();plotPage();}};});}
function currentMap(){const maps=world().maps;return maps.find(m=>m.id===selectedMap)||maps[0];}
function mapSelect(){return `<select id="mapSelect" aria-label="Selecionar mapa" style="max-width:260px">${world().maps.map(m=>`<option value="${m.id}" ${currentMap()?.id===m.id?'selected':''}>${e(m.name)}</option>`).join('')}</select>`;}
function mapsPage(){cleanup();cleanup=()=>{};const m=currentMap();selectedMap=m?.id||'';const pin=m?.pins.find(p=>p.id===selectedPin)||m?.pins[0];selectedPin=pin?.id||'';main.innerHTML=`<div class="page">${heading('CADA LUGAR GUARDA UMA HISTÓRIA','Atlas de mapas','Desenhe caminhos, marque regiões e descubra o que existe além.',btn('＋ Adicionar mapa','map'))}<div class="toolbar">${mapSelect()}${m?btn('⌖ Adicionar região','placePin','ghost')+btn('Renomear','renameMap','ghost')+btn('Excluir mapa','deleteMap','ghost'):''}</div>${m?`<div class="map-layout"><div class="map-canvas" id="mapCanvas"><div class="map-transform" id="mapTransform"><img src="${imageURL(m.image)}" alt="${e(m.name)}" draggable="false">${m.pins.map((p,i)=>`<button class="map-pin ${p.id===selectedPin?'selected':''}" data-pin="${p.id}" style="left:${p.x}%;top:${p.y}%" title="${e(p.name)}" aria-label="${e(p.name)}"><span>${i+1}</span></button>`).join('')}</div><span class="map-hint" id="mapHint">Arraste para explorar · Use + e − para aproximar</span><div class="map-tools"><button id="mapZoomOut" aria-label="Diminuir zoom">−</button><button id="mapZoomIn" aria-label="Aumentar zoom">＋</button><button id="mapReset" aria-label="Restaurar posição">↺</button></div></div><aside class="region-panel">${pin?`${imageURL(pin.image)?`<img src="${imageURL(pin.image)}" alt="${e(pin.name)}">`:''}<span class="eyebrow">REGIÃO DO SEU MUNDO</span><h2>${e(pin.name)}</h2><p>${e(pin.description||'Ainda há muito a descobrir sobre este lugar.')}</p><div class="region-actions">${btn('Editar região','editPin')}${btn('Excluir','deletePin','ghost')}</div>`:'<span class="eyebrow">TERRAS INEXPLORADAS</span><h2>Uma história em cada ponto.</h2><p>Adicione uma região no mapa para registrar sua descrição e uma imagem.</p>'}<div class="region-list"><span class="eyebrow">${m.pins.length} REGIÕES</span>${m.pins.map((p,i)=>`<button data-pin="${p.id}">⌖ ${i+1}. ${e(p.name)}</button>`).join('')}</div></aside></div>`:`<div class="empty"><h2>Há um mundo por descobrir.</h2><p>Importe seu primeiro mapa para começar.</p>${btn('Adicionar mapa','map')}</div>`}</div>`;$('#mapSelect').onchange=ev=>{selectedMap=ev.target.value;selectedPin='';mapsPage();};if(!m)return;let zoom=1,tx=0,ty=0,drag=null,moved=false;const canvas=$('#mapCanvas'),layer=$('#mapTransform');const transform=()=>layer.style.transform=`translate(${tx}px,${ty}px) scale(${zoom})`;const img=layer.querySelector('img');const dimensions=()=>{const scale=Math.min(layer.clientWidth/img.naturalWidth,layer.clientHeight/img.naturalHeight);return {iw:img.naturalWidth*scale,ih:img.naturalHeight*scale};};const locate=()=>{if(!img.naturalWidth)return;const {iw,ih}=dimensions();layer.querySelectorAll('[data-pin]').forEach(el=>{const p=m.pins.find(p=>p.id===el.dataset.pin);el.style.left=((layer.clientWidth-iw)/2+p.x/100*iw)+'px';el.style.top=((layer.clientHeight-ih)/2+p.y/100*ih)+'px';});};img.onload=locate;if(img.complete)locate();const observer=new ResizeObserver(locate);observer.observe(canvas);cleanup=()=>observer.disconnect();$('#mapZoomIn').onclick=()=>{zoom=Math.min(4,zoom+.25);transform();};$('#mapZoomOut').onclick=()=>{zoom=Math.max(.75,zoom-.25);transform();};$('#mapReset').onclick=()=>{zoom=1;tx=ty=0;transform();};canvas.onpointerdown=ev=>{if(ev.target.closest('button'))return;drag={x:ev.clientX,y:ev.clientY,tx,ty};moved=false;canvas.setPointerCapture(ev.pointerId);};canvas.onpointermove=ev=>{if(!drag||canvas.classList.contains('placing'))return;if(Math.abs(ev.clientX-drag.x)+Math.abs(ev.clientY-drag.y)>4)moved=true;tx=drag.tx+ev.clientX-drag.x;ty=drag.ty+ev.clientY-drag.y;transform();};canvas.onpointerup=ev=>{drag=null;if(!canvas.classList.contains('placing')||moved||ev.target.closest('button'))return;const box=layer.getBoundingClientRect();const img=layer.querySelector('img');const scale=Math.min(layer.clientWidth/img.naturalWidth,layer.clientHeight/img.naturalHeight);const iw=img.naturalWidth*scale,ih=img.naturalHeight*scale;const px=(ev.clientX-box.left)/zoom,py=(ev.clientY-box.top)/zoom;if(px<(layer.clientWidth-iw)/2||px>(layer.clientWidth+iw)/2||py<(layer.clientHeight-ih)/2||py>(layer.clientHeight+ih)/2){toast('Clique dentro da área do mapa.');return;}editPin(null,{x:Math.max(0,Math.min(100,(px-(layer.clientWidth-iw)/2)/iw*100)),y:Math.max(0,Math.min(100,(py-(layer.clientHeight-ih)/2)/ih*100))});};}
function globePage(){cleanup();cleanup=()=>{};const w=world(),m=currentMap(),useDefault=w.globeUseDefault||!m,src=useDefault?'assets/eldoria.svg':imageURL(m.image),name=useDefault?'Eldoria — mapa padrão':m.name;main.innerHTML=`<div class="page">${heading('VEJA SEU UNIVERSO POR INTEIRO','Globo 3D','Arraste o seu mundo na mesma direção do olhar.',btn('＋ Importar mapa','map'))}<div class="toolbar">${mapSelect()}<span class="help">${useDefault?'Mapa padrão ativo · ':''}Para melhores resultados, use mapas equiretangulares (2:1).</span></div><div class="map-layout"><div class="globe-stage" style="--globe-background:${/^#[0-9a-f]{6}$/i.test(w.globeBackground||'')?w.globeBackground:'#b8c7ad'}"><div class="globe-top-controls"><button id="expandGlobe" class="button ghost" aria-label="Expandir globo" aria-expanded="false">⛶ Expandir</button><label class="globe-bg-control">Fundo <input type="color" id="globeBackground" value="${/^#[0-9a-f]{6}$/i.test(w.globeBackground||'')?w.globeBackground:'#b8c7ad'}" aria-label="Cor do fundo do globo"></label><button class="button ghost" id="resetGlobeMap">↺ Mapa padrão</button></div><canvas id="globe" aria-label="Globo 3D interativo. Arraste para girar e use a roda do mouse para aproximar."></canvas><div class="globe-caption"><strong>${e(name)}</strong>Arraste para girar · Role para aproximar</div></div><aside class="region-panel"><span class="eyebrow">UMA QUESTÃO DE PERSPECTIVA</span><h2>Seu mundo,<br>em movimento.</h2><p>O mapa escolhido envolve a esfera. Importe suas próprias terras e encontre um novo ponto de vista.</p><label class="field"><span>Rotação automática</span><input style="width:auto;accent-color:#466045" id="rotateGlobe" type="checkbox" checked></label><button id="resetGlobe" class="button ghost">Restaurar visão</button><p class="help" style="margin-top:25px">Mapas planos também funcionam, mas podem apresentar distorção nos polos. Notas e pinagens ficam no Atlas 2D.</p><div id="globeError" role="status"></div></aside></div></div>`;$('#mapSelect').onchange=event=>{selectedMap=event.target.value;w.globeUseDefault=false;persist();globePage();};$('#resetGlobeMap').onclick=()=>{w.globeUseDefault=true;persist();globePage();};const stage=$('.globe-stage');$('#globeBackground').oninput=event=>{w.globeBackground=event.target.value;stage.style.setProperty('--globe-background',event.target.value);scheduleSave();};const abort=new AbortController();const toggle=()=>{const expanded=stage.classList.toggle('globe-expanded');document.body.classList.toggle('globe-focus',expanded);$('#expandGlobe').setAttribute('aria-expanded',String(expanded));$('#expandGlobe').setAttribute('aria-label',expanded?'Restaurar globo':'Expandir globo');$('#expandGlobe').textContent=expanded?'⛶ Restaurar':'⛶ Expandir';};$('#expandGlobe').onclick=toggle;document.addEventListener('keydown',event=>{if(event.key==='Escape'&&stage.classList.contains('globe-expanded'))toggle();},{signal:abort.signal});const stop=mountGlobe($('#globe'),src,message=>$('#globeError').textContent=message);cleanup=()=>{abort.abort();document.body.classList.remove('globe-focus');stop();};}
function settingsPage(){const w=world();main.innerHTML=`<div class="page">${heading('UM ESPAÇO COM A SUA IDENTIDADE','Configurações do ambiente','Cada universo tem seu próprio jeito de existir.')}<div class="settings-grid"><section class="settings-panel"><h2>A identidade do seu mundo</h2><label class="field"><span>Nome do ambiente</span><input id="worldName" value="${e(w.name)}" maxlength="80"></label><label class="field"><span>Descrição curta</span><input id="worldSubtitle" value="${e(w.subtitle)}" maxlength="100"></label>${btn('Salvar alterações','saveWorld')}</section><section class="settings-panel"><h2>Só o que faz sentido para você</h2><p>Escolha as abas deste ambiente. Ao ocultar uma aba, seu conteúdo é preservado.</p>${Object.entries(tabs).filter(([k])=>k!=='home').map(([key,[icon,label]])=>`<label class="toggle"><span>${icon} &nbsp; ${label}</span><input type="checkbox" data-tab="${key}" ${w.enabled.includes(key)?'checked':''}></label>`).join('')}</section><section class="settings-panel"><h2>Seu mundo é seu.</h2><p>Os dados ficam neste navegador, sem conta ou sincronização. Exporte um backup regularmente para preservar suas histórias ou levá-las a outro dispositivo. A importação adiciona os ambientes sem substituir os atuais.</p><div class="toolbar">${btn('↓ Exportar backup','export','ghost')}${btn('↑ Importar backup','import','ghost')}${btn('＋ Novo ambiente','world','ghost')}</div><p class="help">Imagens são otimizadas na importação. O espaço disponível depende do navegador.</p></section><section class="settings-panel"><h2>Gerenciar ambiente</h2><p>Excluir este ambiente remove suas notas, fichas e mapas deste navegador.</p>${btn('Excluir ambiente atual','deleteWorld','danger')}</section></div></div>`;document.querySelectorAll('[data-tab]').forEach(input=>input.onchange=()=>{w.enabled=input.checked?[...new Set([...w.enabled,input.dataset.tab])]:w.enabled.filter(t=>t!==input.dataset.tab);persist();sidebar();});}
function field(label,name,value='',type='text',required=false){return `<label class="field"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" ${required?'required':''}>${e(value)}</textarea>`:`<input type="${type}" name="${name}" value="${e(value)}" ${required?'required':''} maxlength="${type==='text'?300:100000}">`}</label>`;}
function modal(title,body,onSubmit,options={}){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#submitModal').textContent=options.submit||'Salvar';$('.modal-actions').style.display=options.noActions?'none':'flex';$('#modalForm').onsubmit=async ev=>{ev.preventDefault();const button=$('#submitModal');button.disabled=true;try{await onSubmit(new FormData(ev.target));$('#modal').close();}catch(error){toast(error.message||'Não foi possível salvar.');}finally{button.disabled=false;}};$('#modal').showModal();}
function confirmDelete(title,description,action){modal(title,`<p class="help">${description}</p>`,()=>{action();persist();sidebar();render();toast('Excluído.');},{submit:'Excluir'});}
function newNote(){const w=world(),inFolder=view==='folder',folder=inFolder?folderFilter:'';modal('Uma nova página',field('Título','title','','text',true)+(inFolder?'<p class="help">Este documento pertence apenas à pasta '+e(w.folders.find(f=>f.id===folder)?.name||'')+'.</p>':'<p class="help">Esta nota ficará na aba Notas & documentos.</p>'),fd=>{const n={id:uid(),title:fd.get('title').trim()||'Sem título',folder,body:'',updated:new Date().toISOString()};(inFolder?w.folderNotes:w.notes).unshift(n);if(!inFolder&&!w.enabled.includes('notes'))w.enabled.push('notes');persist();navigate(inFolder?'folder':'notes',{note:n.id,folder});});}
function editEntity(kind,id){const w=world(),item=w[kind].find(i=>i.id===id),creature=kind==='bestiary';modal(item?`Ficha de ${item.name}`:creature?'Uma nova criatura':'Um novo personagem',field('Nome','name',item?.name||'','text',true)+`<div class="field-grid">${field(creature?'Categoria':'Papel na história','role',item?.role||'')}${field('Espécie / raça','species',item?.species||'')}${field('Idade','age',item?.age||'')}</div>`+field('Descrição e personalidade','description',item?.description||'','textarea')+field(creature?'Habitat':'Motivações e desejos','motivation',item?.motivation||'','textarea')+field(creature?'Habilidades e fraquezas':'Conflito e segredos','conflict',item?.conflict||'','textarea')+`<label class="field"><span>Imagem da ficha (opcional)</span><input name="image" type="file" accept="image/*"></label>${imageURL(item?.image)?`<img class="image-preview" src="${imageURL(item.image)}" alt="Imagem atual"><label class="help"><input name="removeImage" type="checkbox" style="width:auto"> Remover imagem atual</label>`:''}${item?'<button type="button" class="text-link" id="deleteEntity">Excluir ficha</button>':''}`,async fd=>{let image=item?.image||'';if(fd.get('removeImage'))image='';if(fd.get('image')?.size)image=await imageFile(fd.get('image'));const data={id:item?.id||uid(),name:fd.get('name').trim()||'Sem nome',role:fd.get('role'),species:fd.get('species'),age:fd.get('age'),description:fd.get('description'),motivation:fd.get('motivation'),conflict:fd.get('conflict'),image};if(item)Object.assign(item,data);else w[kind].push(data);if(!w.enabled.includes(kind))w.enabled.push(kind);persist();navigate(kind);});if(item)$('#deleteEntity').onclick=()=>{$('#modal').close();confirmDelete('Excluir ficha?',`A ficha de ${e(item.name)} será removida.`,()=>w[kind]=w[kind].filter(i=>i.id!==item.id));};}
function editPlot(id,status='idea'){const w=world(),p=w.plot.find(p=>p.id===id);modal(p?'Editar acontecimento':'Um novo acontecimento',field('Título','title',p?.title||'','text',true)+field('Descrição da cena','description',p?.description||'','textarea')+field('Ato / capítulo','act',p?.act||'Ato I')+`<label class="field"><span>Progresso</span><select name="status">${Object.entries(stages).map(([key,label])=>`<option value="${key}" ${(p?.status||status)===key?'selected':''}>${label}</option>`).join('')}</select></label>${p?'<button type="button" class="text-link" id="deletePlot">Excluir acontecimento</button>':''}`,fd=>{const data={id:p?.id||uid(),title:fd.get('title').trim()||'Sem título',description:fd.get('description'),act:fd.get('act'),status:fd.get('status')};if(p)Object.assign(p,data);else w.plot.push(data);persist();navigate('plot');});if(p)$('#deletePlot').onclick=()=>{$('#modal').close();confirmDelete('Excluir acontecimento?','Esta cena será removida da trama.',()=>w.plot=w.plot.filter(i=>i.id!==p.id));};}
