function addMap(){modal('Um novo horizonte',field('Nome do mapa','name','','text',true)+'<label class="field"><span>Arquivo de mapa</span><input name="image" type="file" accept="image/*" required></label><p class="help">PNG, JPG, WebP e outras imagens aceitas pelo navegador. Para o globo, prefira proporção 2:1. Imagens de até 25 MB serão otimizadas.</p>',async fd=>{const image=await imageFile(fd.get('image')),m={id:uid(),name:fd.get('name').trim()||'Meu mapa',image,pins:[]};world().maps.push(m);selectedMap=m.id;selectedPin='';world().globeUseDefault=false;persist();navigate(view==='globe'?'globe':'maps');});}
function addWorld(){modal('Um universo só seu',field('Nome do ambiente','name','','text',true)+field('Descrição curta','subtitle','Um novo universo')+'<p class="help">Cada ambiente tem suas próprias notas, mapas, fichas e configurações.</p>',fd=>{const w=createWorld(fd.get('name').trim()||'Novo universo');w.subtitle=fd.get('subtitle');state.worlds.push(w);state.current=w.id;selectedNote=selectedMap=selectedPin='';persist();navigate('home');});}
function switchWorld(){modal('Seus universos',`<div class="choice-list">${state.worlds.map(w=>`<button type="button" data-world="${w.id}"><span class="world-icon">✧</span><span>${e(w.name)}<small>${e(w.subtitle)}</small></span>${w.id===state.current?'<span class="chevron">✓</span>':''}</button>`).join('')}<button type="button" data-action="world">＋ Criar novo ambiente</button></div>`,()=>{},{noActions:true});}
function createMenu(){modal('O que vamos imaginar?',`<div class="choice-list">${[['note','▤','Documento','Uma página para suas ideias.'],['character','♙','Personagem','Alguém com uma história para contar.'],['plot','⌘','Acontecimento','O próximo passo da sua trama.'],['map','♧','Mapa','Terras que esperam ser descobertas.'],['beast','♧','Criatura','Um encontro com o extraordinário.'],['folder','▱','Pasta','Um lugar para organizar suas notas.']].map(([action,icon,title,desc])=>`<button type="button" data-action="${action}"><span class="nav-icon">${icon}</span><span>${title}<small>${desc}</small></span></button>`).join('')}</div>`,()=>{},{noActions:true});}
function search(){modal('Encontre no seu universo','<input type="search" id="globalSearch" placeholder="Busque notas, personagens, lugares…" aria-label="Buscar no universo"><div class="search-results" id="searchResults"></div>',()=>{},{noActions:true});const w=world();const results=[...w.notes.map(n=>({id:n.id,type:'notes',title:n.title,description:plain(n.body),label:'Nota'})),...w.folderNotes.map(n=>({id:n.id,type:'folder',folder:n.folder,title:n.title,description:plain(n.body),label:'Documento de pasta'})),...['characters','bestiary'].flatMap(type=>w[type].map(i=>({id:i.id,type,title:i.name,description:i.description,label:tabs[type][1]}))),...w.plot.map(p=>({id:p.id,type:'plot',title:p.title,description:p.description,label:'Trama'})),...w.maps.flatMap(m=>[{id:m.id,type:'maps',title:m.name,description:'',label:'Mapa'},...m.pins.map(p=>({id:m.id,pin:p.id,type:'maps',title:p.name,description:p.description,label:'Região'}))])];function show(q){const found=results.filter(r=>(r.title+' '+r.description).toLocaleLowerCase('pt-BR').includes(q.toLocaleLowerCase('pt-BR'))).slice(0,30);$('#searchResults').innerHTML=found.map((r,i)=>`<button type="button" class="search-result" data-result="${i}">${e(r.title)}<small>${r.label}${r.type==='folder'||w.enabled.includes(r.type)?'':' · Aba oculta (será ativada)'}</small></button>`).join('')||'<p class="help" style="padding:15px">Nada encontrado. Tente outra palavra.</p>';document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const r=found[+b.dataset.result];$('#modal').close();if(r.type!=='folder'&&!w.enabled.includes(r.type))w.enabled.push(r.type);if(r.type==='notes'||r.type==='folder')navigate(r.type,{note:r.id,folder:r.folder||''});else if(r.type==='maps'){selectedMap=r.id;selectedPin=r.pin||'';navigate('maps');}else{navigate(r.type);if(r.type==='plot')editPlot(r.id);else editEntity(r.type,r.id);}});}show('');$('#globalSearch').oninput=ev=>show(ev.target.value);setTimeout(()=>$('#globalSearch').focus(),20);}
function exportBackup(){persist();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`aethra-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exportado. Guarde-o em um lugar seguro.');}
function validateBackup(data){if(data.version!==1||!Array.isArray(data.worlds)||!data.worlds.length||data.worlds.length>100)throw Error('Este arquivo não é um backup Aethra válido.');for(const w of data.worlds){prepareWorld(w);initNarrative(w);for(const scene of w.narrative.scenes){if(typeof scene.body!=='string'||typeof scene.title!=='string')throw Error('Cena inválida.');scene.body=sanitize(scene.body);}if(typeof w.name!=='string'||!Array.isArray(w.enabled)||!Array.isArray(w.folders)||!Array.isArray(w.notes)||!Array.isArray(w.characters)||!Array.isArray(w.bestiary)||!Array.isArray(w.plot)||!Array.isArray(w.maps))throw Error('O backup está incompleto.');w.id=uid();w.subtitle=String(w.subtitle||'');w.enabled=['home',...w.enabled.filter(t=>tabs[t]&&t!=='home')];for(const f of w.folders)if(typeof f.id!=='string'||typeof f.name!=='string')throw Error('Pasta inválida.');for(const event of w.calendarEvents){if(!validDate(event.date)||typeof event.title!=='string')throw Error('Evento inválido no calendário.');event.id=typeof event.id==='string'?event.id:uid();event.description=String(event.description||'');event.time=/^([01]\d|2[0-3]):[0-5]\d$/.test(event.time||'')?event.time:'';event.target=String(event.target||'');}for(const n of [...w.notes,...w.folderNotes]){n.emoji=String(n.emoji||'').slice(0,12);if(typeof n.id!=='string'||typeof n.title!=='string'||typeof n.body!=='string')throw Error('Documento inválido.');n.body=sanitize(n.body);n.updated=String(n.updated||new Date().toISOString());}for(const kind of ['characters','bestiary'])for(const i of w[kind]){if(typeof i.name!=='string')throw Error('Ficha inválida.');i.id=typeof i.id==='string'?i.id:uid();for(const k of ['role','species','age','description','motivation','conflict'])i[k]=String(i[k]||'');i.image=imageURL(i.image);}for(const p of w.plot){if(typeof p.title!=='string')throw Error('Trama inválida.');p.id=typeof p.id==='string'?p.id:uid();p.description=String(p.description||'');p.act=String(p.act||'');if(!stages[p.status])p.status='idea';}for(const m of w.maps){if(typeof m.name!=='string'||!Array.isArray(m.pins))throw Error('Mapa inválido.');m.image=imageURL(m.image)||'assets/eldoria.svg';m.id=typeof m.id==='string'?m.id:uid();for(const p of m.pins){if(typeof p.name!=='string'||!Number.isFinite(p.x)||!Number.isFinite(p.y))throw Error('Região inválida.');p.id=typeof p.id==='string'?p.id:uid();p.x=Math.min(100,Math.max(0,p.x));p.y=Math.min(100,Math.max(0,p.y));p.image=imageURL(p.image);p.description=String(p.description||'');}}}return data.worlds;}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('O backup deve ter até 30 MB.');const worlds=validateBackup(JSON.parse(await file.text()));const previous=state.worlds;state.worlds=[...previous,...worlds];if(!save()){state.worlds=previous;throw Error('Sem espaço para importar. Os ambientes atuais foram preservados.');}navigate('settings');toast(`${worlds.length} ambiente(s) importado(s).`);}catch(err){toast(err instanceof SyntaxError?'Arquivo JSON inválido.':err.message);}};input.click();}
