document.addEventListener('click',ev=>{const el=ev.target.closest('button');if(!el)return;if(el.dataset.view){if($('#modal').open)$('#modal').close();navigate(el.dataset.view);return;}if(el.dataset.folder){navigate('folder',{folder:el.dataset.folder});return;}if(el.dataset.note){navigate(view==='folder'?'folder':'notes',{note:el.dataset.note,folder:view==='folder'?folderFilter:''});return;}if(el.dataset.entity){editEntity(el.dataset.kind,el.dataset.entity);return;}if(el.dataset.plot){editPlot(el.dataset.plot);return;}if(el.dataset.pin){selectedPin=el.dataset.pin;mapsPage();return;}if(el.dataset.world){$('#modal').close();persist();state.current=el.dataset.world;selectedNote=selectedMap=selectedPin='';navigate('home');return;}if(el.dataset.action&&actions[el.dataset.action]){if($('#modal').open)$('#modal').close();actions[el.dataset.action](el);}});
$('.brand').onclick=ev=>{ev.preventDefault();navigate('home');};$('#closeModal').onclick=$('#cancelModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close();}});$('#workspaceButton').onclick=switchWorld;$('#searchButton').onclick=search;$('#searchButton kbd').textContent=isMac?'⌘ K':'Ctrl K';$('#searchButton').title=`Buscar no universo (${isMac?'⌘':'Ctrl'} + K)`;$('#newButton').onclick=createMenu;$('#addFolder').onclick=actions.folder;$('#themeButton').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';document.body.classList.toggle('dark',state.theme==='dark');persist();};initSidebar();document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();if($('#modal').open)$('#modal').close();search();}if(ev.key==='Escape')closeMobileSidebar();});window.addEventListener('pagehide',()=>{persist();cleanup();});document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();});sidebar();render();

